{
  "up": "Select molecule_dictionary.chembl_id AS chembl_id, molecule_dictionary.pref_name AS pref_name, compound_structures.canonical_smiles AS canonical_smiles, drug_indication.mesh_id AS indication_curie, drug_indication.mesh_heading AS indication_label, drug_indication.max_phase_for_ind AS max_phase_for_ind From molecule_dictionary Join drug_indication On molecule_dictionary.molregno = drug_indication.molregno Join compound_structures On molecule_dictionary.molregno = compound_structures.molregno Where drug_indication.mesh_heading = 'Infection' And drug_indication.max_phase_for_ind = 4 Order By chembl_id, pref_name, canonical_smiles, indication_curie, indication_label, max_phase_for_ind"
}
